<template>
  <div class="detail-page"><div class="container detail-nav"><RouterLink to="/orders"><el-icon><ArrowLeft /></el-icon>返回我的定制</RouterLink><span v-if="order">订单号 {{ order.order_no }}</span></div>
    <div v-if="loading" class="container detail-loading skeleton"></div><template v-else-if="order">
      <div class="container status-hero"><div class="status-copy"><span class="eyebrow">CREATION JOURNEY</span><h1 class="serif">{{ statusLabel(order.status) }}</h1><p>{{ statusDescription }}</p><button v-if="['PENDING_CONFIRM','DESIGN_CONFIRM'].includes(order.status)" class="btn btn-primary" :disabled="confirming" @click="confirmDesign"><el-icon><CircleCheck /></el-icon>{{ confirming?'正在确认…':'确认定稿，开始创作' }}</button><button v-else-if="order.status==='SHIPPED'" class="btn btn-primary" @click="ElMessage.success('已提醒平台确认收货，演示流程完成')">确认收货</button></div><div class="status-art"><img :src="mediaUrl(order.media_asset?.url)" alt="定稿形象"/><span class="seal">创作</span></div><div class="order-meta"><div><small>定制载体</small><strong>{{ order.product?.name||'东方形象定制' }}</strong></div><div><small>创作画师</small><strong>{{ order.artist?.pen_name||order.artist?.name||'平台精心匹配中' }}</strong></div><div><small>预计交付</small><strong>{{ order.status==='COMPLETED'?'已交付':`下单后 ${order.product?.lead_time_days||7} 个工作日` }}</strong></div></div></div>
      <div class="container stepper-wrap"><div class="stepper" role="list" aria-label="创作进度"><div v-for="(step,i) in steps" :key="step" class="step" role="listitem" :class="{done:currentStep>i,active:currentStep===i}" :aria-current="currentStep===i?'step':undefined"><div class="step-marker"><el-icon v-if="currentStep>i"><Check /></el-icon><span v-else>{{ i+1 }}</span></div><span>{{ step }}</span><small v-if="currentStep===i" class="sr-only">当前阶段</small></div></div></div>
      <div class="container detail-layout"><main>
        <section v-if="['PENDING_CONFIRM','DESIGN_CONFIRM'].includes(order.status)" class="confirm-card"><div class="confirm-icon"><el-icon><Picture /></el-icon></div><div><h3 class="serif">最后看一眼，再让画师落笔</h3><p>请确认人物形象、画幅与定制细节。定稿后作品进入创作阶段，如需调整可在开始前联系运营。</p><button class="text-link" @click="previewOpen=true">查看定稿大图与定制细节<el-icon><ArrowRight /></el-icon></button></div><button class="btn btn-primary" @click="confirmDesign">确认无误</button></section>
        <section class="timeline-section paper-card"><div class="card-section-head"><div><span class="eyebrow">LIVE UPDATES</span><h2 class="serif">创作手记</h2></div><span class="update-count">{{ posts.length }} 条进度</span></div>
          <div v-if="posts.length" class="timeline"><article v-for="(post,i) in posts" :key="post.id||i" class="timeline-item"><div class="timeline-rail"><span class="timeline-node"><el-icon><Brush /></el-icon></span><i></i></div><div class="timeline-content"><div class="post-meta"><h3 class="serif">{{ post.step_name }}</h3><time>{{ dateTime(post.created_at) }}</time></div><p>{{ post.content }}</p><div v-if="postImages(post).length" class="post-images" :class="{single:postImages(post).length===1}"><button v-for="(img,j) in postImages(post)" :key="j" :aria-label="`查看${post.step_name}实拍大图`" @click="previewImage=mediaUrl(img)"><img :src="mediaUrl(img)" :alt="post.step_name+'实拍'" loading="lazy"/><span><el-icon><FullScreen /></el-icon></span></button></div><div class="artist-sign"><span class="mini-avatar">{{ (order.artist?.pen_name||'镜').slice(0,1) }}</span><span>{{ order.artist?.pen_name||'镜绘签约画师' }} · 创作现场</span><span class="verified"><el-icon><CircleCheck /></el-icon>平台记录</span></div></div></article></div>
          <div v-else class="timeline-empty"><div class="ink-wait"><el-icon><Brush /></el-icon></div><h3 class="serif">匠人正在准备，第一手创作手记即将抵达</h3><p>每当作品进入新的创作节点，我们都会在这里同步实拍与说明。</p></div>
        </section>
