import { computed, onMounted, ref } from 'vue';import { useRoute } from 'vue-router';import { ElMessage } from 'element-plus';import { mediaUrl, orderApi } from '@/services/api';import { dateTime, money, statusLabel } from '@/utils/format'
const route=useRoute(),order=ref<any>(null),history=ref<any[]>([]),posts=ref<any[]>([]),loading=ref(true),confirming=ref(false),previewOpen=ref(false),previewImage=ref('')
const steps=['定稿确认','交付画师','亲笔创作','质检装裱','成品发货','珍藏到家']
const stepIndex:Record<string,number>={PENDING_CONFIRM:0,DESIGN_CONFIRM:0,ASSIGNED:1,IN_PRODUCTION:2,QUALITY_CHECK:3,SHIPPED:4,COMPLETED:5}
const descMap:Record<string,string>={PENDING_CONFIRM:'请确认 AI 定稿与定制细节，画师将在确认后开始创作。',DESIGN_CONFIRM:'请确认 AI 定稿与定制细节，画师将在确认后开始创作。',ASSIGNED:'你的定稿已交付签约画师，正在准备纸笔与颜料。',IN_PRODUCTION:'画师正在亲笔创作，关键节点将通过实拍与你分享。',QUALITY_CHECK:'作品主体已完成，正在仔细质检并为其装裱。',SHIPPED:'你的专属作品已悉心打包，正奔赴你的手中。',COMPLETED:'作品已抵达，愿这份独一无二长久陪伴你。'}
const currentStep=computed(()=>stepIndex[order.value?.status]??0)
const statusDescription=computed(()=>descMap[order.value?.status]||'')
onMounted(load)
async function load(){try{const id=Number(route.params.id);const [detail,timeline]=await Promise.all([orderApi.detail(id),orderApi.timeline(id)]);order.value=detail;const t:any=timeline;history.value=Array.isArray(t)?t:(t.history||t.status_history||t.timeline||[]);posts.value=(Array.isArray(t)?[]:(t.progress||t.progress_posts||t.posts||[])).concat(detail.progress_posts||[]).filter((v:any,i:number,a:any[])=>a.findIndex(x=>x.id===v.id)===i);if(!posts.value.length)posts.value=detail.progress_posts||[]}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}
async function confirmDesign(){confirming.value=true;try{await orderApi.confirm(order.value.id);ElMessage.success('定稿已确认，画师即将开始创作');await load()}catch(e:any){ElMessage.error(e.message)}finally{confirming.value=false}}
function postImages(post:any){if(post.media_urls)return post.media_urls;if(post.images)return post.images;if(post.media)return post.media.map((m:any)=>typeof m==='string'?m:m.url);return []}
function formatSpecialties(s:any){return Array.isArray(s)?s.join(' · '):s||'传统人物画'}
</script>
